// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder callee;

    function setUp() public { 
        c = new airPort();
        callee = new Recorder();
    }

    // fuzz parameters: from address, a recipient address entry, uint256 v, and uint256 tosLen
    function testFuzz_property(address from, address recip, uint256 v, uint256 tosLen) public {
        // admissible domain: _tos.length must be > 0 as required by contract
        // keep tosLen reasonably bounded and ensure at least 1
        tosLen = bound(tosLen, 1, 3);

        // build _tos array of length tosLen filled with the fuzzed recip
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) tos[i] = recip;

        // ensure the callee is the counterparty so we can observe the external calls
        address caddress = address(callee);

        // Call transfer and observe whether it reverts. The reference C should never revert
        // for any v (including 0) when _tos.length > 0; the mutant with require(v>0) will revert
        // for v == 0. We record the call success into ok.
        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: for any admissible inputs (tosLen >= 1), the reference never reverts,
        // so ok must be true. This will fail for the mutant when v==0.
        assertTrue(ok);
    }
}

// Recorder that exposes the same transferFrom(address,address,uint256) selector
// so C's low-level call decodes and hits this function. It records calls made to it.
contract Recorder {
    event Called(address from, address to, uint256 v);

    // match selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        // record that we were called (keeps behaviour visible to tests via logs)
        emit Called(from, to, v);
        return true;
    }
}
